      '대만 시가총액 상위 50대 상장·장외 기업의 시가총액, 매출, 직원 수를 인터랙티브 버블 차트로 보고, AI 공급망이 순위를 계속 어떻게 바꾸는지 살펴봅니다(2026/10/22 스냅샷).',
